import cls from 'classnames';
import React from 'react';

import { RicosContext } from './../../../ricos-context/index.js';

import { LoaderIcon } from '../../assets/icons/loader-icon.js';
import type { RCEHelpersProps } from '../rce-helpers-context/index.js';
import { withRCEHelpers } from '../rce-helpers-context/index.js';
import styles from './text-field-scss.js';

type Props = RCEHelpersProps & {
  dataHook?: string;
  autofocus?: boolean;
  maxLength?: number;
  value?: string;
  disabled?: boolean;
  className?: string;
  onChange?: (...args: $TSFixMe[]) => void;
  placeholder?: string;
  textAutoResize?: boolean;
  startAdornment?: React.ReactNode;
  endAdornment?: React.ReactNode;
  children?: React.ReactNode;
  style?: React.CSSProperties;
};

class TextFieldComponent extends React.PureComponent<Props> {
  static defaultProps = {
    maxLength: 500,
    disabled: false,
  };

  $el = React.createRef();

  state = {
    placeholder: this.props.placeholder,
    rows: 1,
    syncing: false,
    isFocused: false,
  };

  static contextType = RicosContext;

  componentDidMount() {
    const { rce } = this.props;
    const isEditMode = !rce.isViewMode;

    if (isEditMode) {
      this.resize();
    }

    this.handleAutoFocus();

    window?.addEventListener('resize', this.handleWindowResizeEvent);
  }

  componentDidUpdate(props: $TSFixMe) {
    if (this.props.rce.isViewMode === props.rce.isViewMode) {
      return;
    }

    this.handleAutoFocus();
  }

  handleAutoFocus() {
    const { rce, autofocus } = this.props;
    const isEditMode = !rce.isViewMode;

    // Only autofocus if this is truly a single node selection, not part of a larger selection
    if (autofocus && isEditMode && rce.isOnlySelected) {
      // @ts-expect-error
      this.$el.current?.focus();
    }
  }

  componentWillUnmount() {
    window?.removeEventListener('resize', this.handleWindowResizeEvent);
  }

  handleWindowResizeEvent = () => setTimeout(() => this.resize());

  hidePlaceholder() {
    this.setState({ placeholder: '' });
  }

  showPlaceholder() {
    this.setState({ placeholder: this.props.placeholder });
  }

  handleFocus = (e: $TSFixMe) => {
    e.stopPropagation();
    setTimeout(() => this.resize());
    this.hidePlaceholder();
    this.props.rce.setInPluginEditingMode(true);
    this.setState({ isFocused: true });
  };

  handleKeyDown(event: React.KeyboardEvent) {
    if (event.key === 'Enter') {
      event.preventDefault();
    }
  }

  handleBlur = () => {
    setTimeout(() => this.resize());
    this.showPlaceholder();
    this.props.rce.setInPluginEditingMode(false);
    this.setState({ isFocused: false });
  };

  handleChange = (event: $TSFixMe) => {
    this.props.onChange?.(event.target.value);

    this.resize();
  };

  resize() {
    const { jsdomMode } = this.context as $TSFixMe;
    if (!this.$el.current || jsdomMode) {
      return;
    }

    // @ts-expect-error
    const computedStyles = getComputedStyle(this.$el.current);

    const lineHeight = parseInt(computedStyles.lineHeight);
    const paddingTop = parseInt(computedStyles.paddingTop);
    const paddingBottom = parseInt(computedStyles.paddingBottom);

    // @ts-expect-error
    this.$el.current.rows = 1;

    // @ts-expect-error
    const { scrollHeight } = this.$el.current;

    // @ts-expect-error
    this.$el.current.rows = this.state.rows;

    const contentHeight = scrollHeight - (paddingTop + paddingBottom);
    const rows = Math.ceil(Math.min(Math.max(contentHeight / lineHeight, 1), Infinity));

    this.setState({ rows });
  }

  render() {
    const {
      dataHook,
      textAutoResize,
      className,
      rce,
      endAdornment,
      style,
      children,
      startAdornment,
      maxLength,
      disabled,
      value,
    } = this.props;

    const { placeholder, rows, syncing, isFocused } = this.state;

    if (rce.isViewMode || rce.isPreview) {
      return (
        <>
          <p
            style={style}
            className={cls(
              styles.text,
              className,
              textAutoResize && {
                [styles.small]: (value?.length ?? 0) > 120,
                [styles.medium]: (value?.length ?? 0) <= 120,
                [styles.large]: (value?.length ?? 0) <= 80,
              },
              {
                [styles.webview]: rce.isWebView,
              }
            )}
          >
            {startAdornment}
            {children}
            <span className={styles.value} data-hook={dataHook}>
              {this.props.value || this.props.placeholder}
            </span>
          </p>
        </>
      );
    }

    return (
      <div className={styles.root}>
        {startAdornment}
        <textarea
          data-hook={dataHook}
          disabled={disabled}
          maxLength={maxLength}
          style={style}
          // @ts-expect-error
          ref={this.$el}
          onChange={this.handleChange}
          onFocus={this.handleFocus}
          onBlur={this.handleBlur}
          placeholder={placeholder}
          value={value}
          rows={rows}
          onKeyDown={this.handleKeyDown}
          className={cls(
            styles.input,
            className,
            textAutoResize && {
              [styles.small]: (value?.length ?? 0) > 120,
              [styles.medium]: (value?.length ?? 0) <= 120,
              [styles.large]: (value?.length ?? 0) <= 80,
            }
          )}
          onClick={undefined}
        />
        <span
          className={cls(styles.endAdornment, {
            [styles.shown]: syncing || isFocused,
          })}
        >
          {syncing ? <LoaderIcon className={styles.spinner} /> : endAdornment}
        </span>
      </div>
    );
  }
}

export const TextField = withRCEHelpers(TextFieldComponent);
