import { LayoutGallery } from '@wix/wix-ui-icons-common/lazy';
import React from 'react';

import { TIPTAP_POLL_TYPE } from './../ricos-content/index.js';
import type { Resolver, RicosServices, ToolbarButton } from './../ricos-types/index.js';
import { createAnimationButton } from './../_shared/plugin-toolbar/create-animation-button.js';
import { createDeleteButton } from './../_shared/plugin-toolbar/create-delete-button.js';
import { createSettingsButton } from './../_shared/plugin-toolbar/create-settings-button.js';
import { createSeparator } from './../_shared/plugin-toolbar/separator/create-separator.js';
import { getNodeInSelection } from './../_shared/resolvers/get-node-in-selection.js';
import type { Node as ProseMirrorNode } from './../tiptap/pm/model.js';
import { FLOATING_PLUGIN_TOOLBAR } from './../toolbars-v3/index.js';

import { SettingsModal } from './components/settings-modal/settings-modal.js';
import type { SettingsType } from './consts.js';
import { POLL_LAYOUT_DROPDOWN_MODAL_ID, POLL_SETTINGS_MODAL_ID, SETTINGS_TAB } from './consts.js';
import { PLUGIN_TOOLBAR_LAYOUT_DROPDOWN_BUTTON } from './data-hooks.js';
import { PollLayoutDropdownButton } from './toolbar/poll-layout-dropdown-button.js';
import type { SupportedLayouts } from './toolbar/poll-layout-dropdown.js';
import { PollLayoutDropdown, dropdownOptions } from './toolbar/poll-layout-dropdown.js';
import type { PollPluginEditorConfig } from './types.js';

export const getToolbarButtons = (
  config: PollPluginEditorConfig,
  services: RicosServices
): ToolbarButton[] => {
  const { modals } = services;
  const { isMobile } = services?.context ?? {};

  const openSettingsModal = ({
    modalId,
    node,
    referenceElement,
    activeTab,
  }: {
    modalId: string;
    node: ProseMirrorNode;
    referenceElement: HTMLElement | undefined;
    activeTab: SettingsType;
  }) => {
    modals?.togglePluginPanel({
      id: modalId,
      Component: SettingsModal,
      componentProps: {
        nodeId: node.attrs.id,
        activeTab,
        config,
        modalId,
      },
      positioning: {
        referenceElement:
          referenceElement?.closest(`[data-hook~=${FLOATING_PLUGIN_TOOLBAR}]`) ?? referenceElement,
        placement: 'right-start',
      },
      focusReturnElement: referenceElement,
      isMobile,
    });
  };

  const settingsButton = createSettingsButton({
    modalId: POLL_SETTINGS_MODAL_ID,
    showLabel: true,
    command: ({ referenceElement, attributes: { selectedNode } }) => {
      openSettingsModal({
        modalId: POLL_SETTINGS_MODAL_ID,
        node: selectedNode,
        referenceElement,
        activeTab: SETTINGS_TAB.settings,
      });
    },
  });
  const separator1 = createSeparator();
  const layoutButton: ToolbarButton = {
    id: POLL_LAYOUT_DROPDOWN_MODAL_ID,
    type: 'modal',
    dataHook: PLUGIN_TOOLBAR_LAYOUT_DROPDOWN_BUTTON,
    attributes: {
      layout: selectedLayoutResolver,
      selectedNode: getNodeInSelection,
      active: (_, { modals }) => Boolean(modals?.getModal(POLL_LAYOUT_DROPDOWN_MODAL_ID)),
    },
    getIcon: ({ attributes }) => {
      const selectedLayout =
        dropdownOptions[attributes.layout as SupportedLayouts] || dropdownOptions.GRID;

      return selectedLayout?.icon || LayoutGallery;
    },
    tooltip: 'Poll_PollSettings_Tab_Layout_TabName',
    command: ({ referenceElement, tiptapEditor, attributes }) => {
      if (modals?.isModalOpen(POLL_LAYOUT_DROPDOWN_MODAL_ID)) {
        modals?.closeModal(POLL_LAYOUT_DROPDOWN_MODAL_ID);
        return;
      }

      modals?.openModal({
        id: POLL_LAYOUT_DROPDOWN_MODAL_ID,
        Component: PollLayoutDropdown,
        componentProps: {
          selectedLayout: attributes?.layout || 'GRID',
          onLayoutClick: layout => {
            tiptapEditor
              .chain()
              .focus()
              .updateAttributes(TIPTAP_POLL_TYPE, {
                layout: {
                  poll: { ...attributes.selectedNode.attrs.layout.poll, type: layout },
                },
              })
              .run();

            modals?.closeModal(POLL_LAYOUT_DROPDOWN_MODAL_ID);
          },
          onCustomizeButtonClick: () => {
            openSettingsModal({
              modalId: POLL_SETTINGS_MODAL_ID,
              node: attributes.selectedNode,
              referenceElement,
              activeTab: SETTINGS_TAB.layout,
            });
          },
        },
        layout: isMobile ? 'drawer' : 'floating',
        positioning: { referenceElement, placement: 'bottom' },
        type: 'exclusive',
      });
    },
    renderer: toolbarItem => <PollLayoutDropdownButton toolbarItem={toolbarItem} />,
  };
  const separator2 = createSeparator();
  const animation = createAnimationButton(services);
  const deleteButton = createDeleteButton();

  if (services.context.environment === 'wixel') {
    return [settingsButton, layoutButton, animation, deleteButton];
  }

  return [settingsButton, separator1, layoutButton, animation, separator2, deleteButton];
};

const selectedLayoutResolver: Resolver<string | undefined> = content => {
  const pollNode = Array.isArray(content) && content.find(node => node.type.name === 'POLL');
  if (!pollNode) {
    return undefined;
  }
  return pollNode.attrs.layout?.poll.type;
};
