import { definePmNodeConverter } from './../pm-converters/types.js';
import type { PmNodeJson } from './../pm-converters/types.js';
import type { PollData, PollNode } from './../ricos-schema/next-schema/index.js';
import { Node_Type } from './../ricos-schema/next-schema/index.js';

export const pollConverter = definePmNodeConverter({
  toPm: {
    types: [Node_Type.POLL],
    convert: (node: PollNode) => ({
      type: Node_Type.POLL,
      attrs: {
        ...node.pollData,
        id: node.id,
      },
    }),
  },
  fromPm: {
    types: [Node_Type.POLL],
    convert: (node: PmNodeJson) => {
      const { id, animation, ...data } = node.attrs || {};
      return {
        type: Node_Type.POLL,
        id,
        nodes: [],
        pollData: {
          ...(data as PollData),
          ...(animation ? { animation } : {}),
        },
      };
    },
  },
});
