import React from 'react';

import { PollData_Layout_PollLayout_Type } from './../../../ricos-schema/legacy/wix/rich_content/v1/index.js';

import type { RCEHelpersProps } from '../rce-helpers-context/index.js';

export type PollOptionBaseProps = RCEHelpersProps & {
  option: $TSFixMe;
  poll: $TSFixMe;
  removeEnabled?: boolean;
  imageEnabled?: boolean;
  voteEnabled?: boolean;
  showResults?: boolean;
  dark?: boolean;
  update: (...args: $TSFixMe[]) => $TSFixMe;
  remove: (...args: $TSFixMe[]) => void;
  vote: (...args: $TSFixMe[]) => $TSFixMe;
  unvote: (...args: $TSFixMe[]) => $TSFixMe;
};

type State = { loading: boolean; checked: boolean };

export class PollOptionBase extends React.PureComponent<PollOptionBaseProps, State> {
  state = {
    loading: false,
    checked: this.isUserChoice(),
  };

  isEditAllowed() {
    return !this.props.option.count && !this.props.rce.isPreview;
  }

  isUserChoice() {
    const { poll, option } = this.props;

    return !!poll.ownVotes?.includes(option.id);
  }

  isViewMode() {
    return this.props.rce.isViewMode;
  }

  isGridLayout() {
    return this.props.layout.poll?.type === PollData_Layout_PollLayout_Type.GRID;
  }

  isListLayout() {
    return this.props.layout.poll?.type === PollData_Layout_PollLayout_Type.LIST;
  }

  isImageEnabled() {
    return this.props.layout.options?.enableImage;
  }

  handleRemove = (e: $TSFixMe) => {
    e.stopPropagation();

    this.props.remove();
  };

  async toggleVote() {
    this.setState({ loading: true });

    try {
      if (this.isUserChoice()) {
        await this.props.unvote(this.props.option.id);
        this.setState({ checked: false });
      } else {
        await this.props.vote(this.props.option.id);
        this.setState({ checked: true });
      }
    } catch {
    } finally {
      this.setState({ loading: false });
    }
  }

  handleVoteClick = async (e: $TSFixMe) => {
    const { validateUser, onBeforeVote, preventInteraction, preventVoting } = this.props.rce;
    const vote = this.props.poll.settings.permissions?.vote;
    const onVoteClick = onBeforeVote || validateUser;
    e.preventDefault();

    if (e.key || preventInteraction || preventVoting) {
      return;
    }

    if (onVoteClick) {
      onVoteClick({ voteRole: vote }).then(this.toggleVote.bind(this), () => {});
    } else {
      this.toggleVote();
    }
  };

  handleTitleChange = (title: string) => {
    const { update, option } = this.props;

    return update({ ...option, title });
  };

  handleImageChange = (url: string) => {
    const { update, option } = this.props;
    const newOption = { ...option, image: { src: { url } } };
    return update(newOption);
  };

  getVotePercentage() {
    const { option } = this.props;

    return option.rating || 0;
  }

  render() {
    if (this.isViewMode()) {
      // @ts-expect-error
      return this.renderViewMode();
    }

    // @ts-expect-error
    return this.renderEditMode();
  }
}
