import type { ReactNode } from 'react';
import React, { useEffect, useLayoutEffect, useRef } from 'react';

// useLayoutEffect warns during SSR; fall back to useEffect on the server.
const useIsomorphicLayoutEffect = typeof window !== 'undefined' ? useLayoutEffect : useEffect;

const REORDER_DURATION_MS = 280;

const prefersReducedMotion = () =>
  typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches;

type Props = {
  className?: string;
  /** Changes whenever the child order changes, triggering the reorder animation. */
  reorderKey: string;
  /** Animate only in the viewer; disabled while editing (matches the old FlipMove behavior). */
  enabled?: boolean;
  children?: ReactNode;
};

/**
 * Renders a `<ul>` and animates its keyed `<li>` children when they change
 * position, using the FLIP technique (measure First & Last positions, Invert
 * via a transform, then Play by transitioning it away). Replaces `react-flip-move`,
 * which only ever animated reordering here. Children must carry a stable
 * `data-flip-key` matching their React `key`.
 */
export const FlipList = ({ className, reorderKey, enabled = true, children }: Props) => {
  const ref = useRef<HTMLUListElement>(null);
  const previousRects = useRef(new Map<string, DOMRect>());

  useIsomorphicLayoutEffect(() => {
    const container = ref.current;
    if (!container) {
      return;
    }

    const nodes = Array.from(container.querySelectorAll<HTMLElement>('[data-flip-key]'));
    const nextRects = new Map(
      nodes.map(node => [node.dataset.flipKey!, node.getBoundingClientRect()])
    );

    if (enabled && !prefersReducedMotion()) {
      nodes.forEach(node => {
        const key = node.dataset.flipKey!;
        const first = previousRects.current.get(key);
        const last = nextRects.get(key);
        // Only animate items present before and after — new items don't animate in.
        if (!first || !last) {
          return;
        }

        const deltaX = first.left - last.left;
        const deltaY = first.top - last.top;
        if (!deltaX && !deltaY) {
          return;
        }

        // Invert: jump the node back to its old position with no transition...
        node.style.transition = 'none';
        node.style.transform = `translate(${deltaX}px, ${deltaY}px)`;

        // ...then Play: on the next frame, transition the transform away.
        requestAnimationFrame(() => {
          node.style.transition = `transform ${REORDER_DURATION_MS}ms ease`;
          node.style.transform = '';
        });
      });
    }

    previousRects.current = nextRects;
  }, [reorderKey]);

  return (
    <ul className={className} ref={ref}>
      {children}
    </ul>
  );
};
