import React, { Component } from 'react';
import InfiniteScroll from 'react-infinite-scroller';

import type { TFunction } from './../../../ricos-types/index.js';

import { LoaderIcon } from '../../assets/icons/loader-icon.js';
import { RemoveIcon } from '../../assets/icons/remove-icon.js';
import type { PollsMember } from '../../types.js';
import { withRCEHelpers } from '../rce-helpers-context/index.js';
import styles from './voted-users-scss.js';
import { VoterAvatar } from './voter-avatar.js';

type Props = {
  fetchVoters: (args: {
    cursor?: string;
    limit: number;
  }) => Promise<{ voters: { memberId: string }[]; moreItems: boolean }>;
  option: {
    count: number;
    anonymousCount: number;
  };
  onRequestClose: () => void;
  t: TFunction;
  rce: {
    getSiteMembers: (memberIds: string[]) => Promise<PollsMember[]>;
  };
};

class VotedUsersModalComponent extends Component<
  Props,
  {
    members: PollsMember[];
    moreItems: boolean;
    cursor?: string;
  }
> {
  state = {
    members: [] as PollsMember[],
    moreItems: true,
    cursor: undefined,
  };

  fetchVoters = async () => {
    const { cursor } = this.state;

    try {
      const { voters, moreItems } = await this.props.fetchVoters({ cursor, limit: 10 });
      const members = (await this.props.rce.getSiteMembers(voters.map(v => v.memberId))) || [];

      this.setState({
        members: this.state.members.concat(members),
        cursor: voters[voters.length - 1].memberId,
        moreItems,
      });
    } catch {
      // Stop the infinite scroll on failure — otherwise `moreItems` stays true
      // and `cursor` never advances, leaving the modal stuck on the loader.
      this.setState({ moreItems: false });
    }
  };

  render() {
    const { t, option, onRequestClose } = this.props;
    const { members, moreItems } = this.state;

    return (
      <div className={styles.voted_users_modal}>
        <div className={styles.voted_users_modal_header}>
          <p className={styles.title}>
            {t('Poll_Viewer_VoteCount_Modal_Voters_Header', {
              count: option.count,
              number: option.count,
            })}
          </p>
          <button
            type="button"
            className={styles.close_button}
            onClick={onRequestClose}
            aria-label={t('Fullscreen_Close_Button_AriaLabel')}
          >
            <RemoveIcon aria-hidden />
          </button>
        </div>
        <InfiniteScroll
          className={styles.member_list_container}
          initialLoad
          hasMore={moreItems}
          loadMore={this.fetchVoters}
          loader={
            <div className={styles.loader}>
              <LoaderIcon width={24} height={24} className={styles.spinner} />
            </div>
          }
        >
          <ul className={styles.member_list}>
            {members.map(member => {
              return member ? (
                <li key={member.siteMemberId}>
                  <div className={styles.user_card}>
                    <VoterAvatar
                      className={styles.user_avatar}
                      member={member}
                      src={member.imageUrl}
                      size={{
                        width: 36,
                        height: 36,
                      }}
                    />
                    <span className={styles.user_name}>
                      {member.name?.nick || t('Poll_Viewer_VoteCount_Modal_Voters_Private_Voter')}
                    </span>
                  </div>
                </li>
              ) : null;
            })}
          </ul>
        </InfiniteScroll>
        {option.anonymousCount ? (
          <p className={styles.anonymous_counter}>
            {t('Poll_Viewer_VoteCount_Modal_Voters_Anonymous', {
              anonNumber: option.anonymousCount,
            })}
          </p>
        ) : null}
      </div>
    );
  }
}

export const VotedUsersModal = withRCEHelpers(VotedUsersModalComponent);
