import cls from 'classnames';
import React, { PureComponent } from 'react';

import { POLLS_QUESTION_IMAGE, POLLS_QUESTION_TEXT_INPUT } from '../../data-hooks.js';
import { ImageUpload } from '../image-upload/image-upload.js';
import { withPoll } from '../poll-context/poll-context.js';
import type { RCEHelpersProps } from '../rce-helpers-context/index.js';
import { withRCEHelpers } from '../rce-helpers-context/index.js';
import { TextField } from '../text-field/text-field.js';
import styles from './poll-header-scss.js';

type Props = RCEHelpersProps & {
  poll: $TSFixMe;
  changePollTitle: (...args: $TSFixMe[]) => void;
  changePollImage: (...args: $TSFixMe[]) => void;
};

class PollHeaderComponent extends PureComponent<Props> {
  render() {
    const { poll, changePollTitle, changePollImage, layout, t, rce } = this.props;

    return (
      <div
        className={cls(styles.header, {
          [styles.webview]: rce.isWebView,
        })}
      >
        <TextField
          autofocus
          textAutoResize
          maxLength={160}
          className={styles.title}
          value={poll.title}
          onChange={changePollTitle}
          placeholder={t('Poll_Editor_Question_Placeholder')}
          dataHook={POLLS_QUESTION_TEXT_INPUT}
        />
        {layout.poll?.enableImage && (
          <ImageUpload
            dataHook={POLLS_QUESTION_IMAGE}
            disabled={rce.isPreview}
            className={styles.image}
            value={poll.image?.src?.url}
            onChange={changePollImage}
          />
        )}
      </div>
    );
  }
}

export const PollHeader = withRCEHelpers(withPoll(PollHeaderComponent));
