import React, { useContext } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';
import { Image } from './../../../ui-components/Components/image.js';

import type { PollsMember } from '../../types.js';
import { FallbackAvatar } from './fallback-avatar.js';

export function VoterAvatar(props: {
  className: string;
  member: PollsMember;
  size: {
    width: number;
    height: number;
  };
  src?: string;
}) {
  const { className, src, member, size } = props;
  const { t } = useContext(RicosContext);

  return src ? (
    <Image
      uri={src}
      displayMode="fill"
      alt={member.name?.nick || t('Polls_Plugin_User_Avatar_Alt')}
      height={size.height}
      width={size.width}
      containerProps={{
        className,
        style: size,
      }}
    />
  ) : (
    <FallbackAvatar className={className} />
  );
}
