import { Statistics, StatisticsSmall } from '@wix/wix-ui-icons-common/lazy';

import type { EditorPluginCreator } from './../ricos-types/index.js';
import {
  Node_Type,
  RicosPluginToolbarNames,
  quickActionsModalSections,
} from './../ricos-types/index.js';
import { posToDOMRect } from './../tiptap/index.js';

import { InsertModal } from './components/insert-modal/insert-modal.js';
import { INSERT_POLL_MODAL_ID } from './consts.js';
import { getAddButtons } from './get-add-buttons.js';
import { getToolbarButtons } from './get-toolbar-buttons.js';
import { pollConverter } from './poll-converter.js';
import { tiptapExtensions } from './tiptap/tiptap.js';
import type { PollPluginEditorConfig } from './types.js';
import { POLL_TYPE } from './types.js';

export const pluginPoll: EditorPluginCreator<PollPluginEditorConfig> = config => {
  return {
    config: { type: 'poll' as const, ...config },
    pmMarkConverters: [],
    pmNodeConverters: [pollConverter],
    type: POLL_TYPE,
    tiptapExtensions,
    getAddButtons: (config, services) => getAddButtons(config, services),
    toolbar: {
      names: [RicosPluginToolbarNames.POLL],
      getButtons: (config, services) => getToolbarButtons(config, services),
    },
    getQuickActions: ({ pluginServices }) => {
      const isMobile = pluginServices?.context.isMobile;

      return [
        {
          id: Node_Type.POLL,
          title: 'QuickActionsPlugin_ActionTitle_Poll',
          icon: isMobile ? Statistics : StatisticsSmall,
          section: quickActionsModalSections.FormatLayout,
          tags: ['vote', 'survey', 'questionnaire', 'feedback', 'voting', 'opinion', 'form'],
          command: ({ modalService, editor }) => {
            modalService.togglePluginPanel({
              id: INSERT_POLL_MODAL_ID,
              Component: InsertModal,
              componentProps: {
                config: { type: 'poll' as const, ...config },
              },
              isMobile,
              positioning: {
                referenceElement: {
                  getBoundingClientRect: () =>
                    posToDOMRect(
                      editor.view,
                      editor.view.state.selection.from,
                      editor.view.state.selection.to
                    ),
                },
                placement: isMobile ? 'bottom' : 'bottom-start',
              },
              mobileLayout: 'drawer',
            });
          },
        },
      ];
    },
  };
};
