import { LayoutGallery } from '@wix/wix-ui-icons-common/lazy';
import type { FC } from 'react';
import React, { useContext, useState } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import { getIsModalOpen, useModalState } from './../../ricos-modals/modal-service-provider.js';
import type { IToolbarItem } from './../../ricos-types/index.js';
import { DropdownButton } from './../../_shared/dropdown-button.js';

import { POLL_LAYOUT_DROPDOWN_MODAL_ID } from '../consts.js';
import type { SupportedLayouts } from './poll-layout-dropdown.js';
import { dropdownOptions } from './poll-layout-dropdown.js';

type Props = {
  toolbarItem: IToolbarItem;
  dataHook?: string;
};

export const PollLayoutDropdownButton: FC<Props> = ({ toolbarItem, dataHook }) => {
  const { t, isMobile } = useContext(RicosContext) || {};
  const isModalOpen = useModalState(getIsModalOpen(POLL_LAYOUT_DROPDOWN_MODAL_ID));
  const [referenceElement, setReferenceElement] = useState<HTMLElement | null>(null);

  const selectedLayout =
    dropdownOptions[toolbarItem?.attributes.layout as SupportedLayouts] || dropdownOptions.GRID;

  return (
    <DropdownButton
      dataHook={dataHook}
      active={isModalOpen}
      onClick={() => toolbarItem.commands?.click({ referenceElement, isMobile })}
      ref={setReferenceElement}
      icon={selectedLayout?.icon || LayoutGallery}
      tooltip={t('Poll_PollSettings_Tab_Layout_TabName')}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
