import { TIPTAP_POLL_TYPE } from './../../ricos-content/index.js';
import type { ExtensionProps, NodeConfig, RicosExtension } from './../../ricos-types/index.js';
import { createRicosNodeExtension } from './../../plugin-commons/index.js';

import { Poll as Component } from './component.js';

const name = TIPTAP_POLL_TYPE;

export const tiptapExtensions = [
  createRicosNodeExtension({
    name,
    groups: ['not-overtypable'],
    type: 'react-node',
    reconfigure: (
      config: NodeConfig,
      _extensions: RicosExtension[],
      _props: ExtensionProps,
      settings: Record<string, unknown>
    ) => ({
      ...config,
      addOptions: () => settings,
    }),
    Component,
    createExtensionConfig() {
      return {
        name: this.name,
        group: 'block smartBlockCellContent layoutCellContent collapsibleListItemBodyContent',
        addAttributes: () => ({
          containerData: null,
          poll: null,
          layout: null,
          design: null,
          loading: {
            default: false,
          },
        }),
        addCommands() {
          return {};
        },
      };
    },
  }),
];
