/* oxlint-disable camelcase */
import type { PollData_Poll_Settings_Permissions_ViewRole } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { PollData_Poll_Settings_Permissions_VoteRole } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';

import type { EnrichedPoll, Poll } from './ricos-types.js';
import type { CreatePollPayload, EnrichedPollServer, PollSettings } from './server-types.js';

export const toPollServer = (poll: EnrichedPoll): EnrichedPollServer => {
  return {
    ...toCreatePollPayload(poll),
    options: poll.options.map(toPollOption),
    id: poll.id,
    createdBy: poll.createdBy,
    count: poll.count,
    anonymousCount: poll.anonymousCount,
    creatorFlag: poll.creatorFlag,
    ownVotes: poll.ownVotes,
  };
};

export const toCreatePollPayload = (poll: Poll): CreatePollPayload => {
  return {
    title: poll.title,
    mediaId: poll.image.src.url,
    ownVotes: [],
    options: poll.options.map(option => ({
      title: option.title,
      mediaId: option.image.src.url,
    })),
    settings: {
      resultsVisibility: getResultsVisibility(poll.settings.permissions?.view),
      multipleVotes: !!poll.settings.permissions?.allowMultipleVotes,
      voteRole: getVoteRole(poll.settings.permissions?.vote),
      votersDisplay: !!poll.settings.showVoters,
      votesDisplay: !!poll.settings.showVotesCount,
    },
  };
};

const toPollOption = (option: EnrichedPoll['options'][0]): EnrichedPollServer['options'][0] => {
  return {
    id: option.id,
    title: option.title,
    mediaId: option.image.src.url,
    count: option.count,
    anonymousCount: option.anonymousCount,
    rating: option.rating,
    latestVoters: option.latestVoters,
  };
};

const getResultsVisibility = (
  view?: PollData_Poll_Settings_Permissions_ViewRole
): PollSettings['resultsVisibility'] =>
  view === 'EVERYONE' ? 'ALWAYS' : view === 'VOTERS' ? 'VOTERS_ONLY' : 'ONLY_ME';

const getVoteRole = (
  vote?: PollData_Poll_Settings_Permissions_VoteRole
): PollSettings['voteRole'] =>
  vote === PollData_Poll_Settings_Permissions_VoteRole.UNRECOGNIZED || vote === undefined
    ? 'ALL'
    : vote;
