import React from 'react';

import { createMediaUploadFn } from './../../../_shared/create-media-upload-fn.js';
import { useWixInstanceService } from './../../../_shared/request-service-provider/wix-instance-context.js';
import { useEditorProps } from './../../../_shared/some-editor-props-context.js';

// Props injected by `withRCEHelpers`. `rce` carries a dynamic set of editor
// helpers/flags that varies by call site, so it stays intentionally loose.
export type RCEHelpersProps = {
  rce: $TSFixMe;
  t: (...args: $TSFixMe[]) => $TSFixMe;
  layout: $TSFixMe;
  design: $TSFixMe;
};

export const RCEHelpersContext = React.createContext({});

// @ts-expect-error
export const withRCEHelpers = WrappedComponent => props => {
  const wixInstance = useWixInstanceService();
  const editorProps = useEditorProps();
  const handleFileUpload = createMediaUploadFn({ wixInstance, editorProps });
  return (
    <RCEHelpersContext.Consumer>
      {/* @ts-expect-error */}
      {({ layout, design, t, ...rest }) => (
        <WrappedComponent
          {...props}
          rce={{ ...rest, handleFileUpload }}
          t={t}
          layout={layout}
          design={design}
        />
      )}
    </RCEHelpersContext.Consumer>
  );
};
