import { Statistics } from '@wix/wix-ui-icons-common/lazy';

import type { AddButton, RicosServices } from './../ricos-types/index.js';
import { Node_Type } from './../ricos-types/index.js';
import { INSERT_PLUGIN_BUTTONS, TOOLBARS } from './../editor-common/index.js';

import { InsertModal } from './components/insert-modal/insert-modal.js';
import { INSERT_POLL_MODAL_ID } from './consts.js';
import { INSERT_POLL_BUTTON } from './data-hooks.js';
import type { PollPluginEditorConfig } from './types.js';

export const toolbarsToAddIn: (TOOLBARS.MOBILE | TOOLBARS.FOOTER | TOOLBARS.SIDE)[] = [
  TOOLBARS.FOOTER,
  TOOLBARS.SIDE,
  TOOLBARS.MOBILE,
];

export const getAddButtons = (
  config: PollPluginEditorConfig,
  services: RicosServices
): AddButton[] => {
  const {
    modals,
    context: { isMobile },
  } = services;

  return [
    {
      id: Node_Type.POLL,
      label: INSERT_PLUGIN_BUTTONS.POLLS,
      dataHook: INSERT_POLL_BUTTON,
      icon: Statistics,
      tooltip: 'Poll_InsertPoll_Tooltip',
      toolbars: [TOOLBARS.MOBILE, TOOLBARS.FOOTER, TOOLBARS.SIDE],
      command: ({ referenceElement }) => {
        modals?.togglePluginPanel({
          id: INSERT_POLL_MODAL_ID,
          Component: InsertModal,
          componentProps: {
            config,
          },
          isMobile,
          positioning: {
            referenceElement,
            placement: 'bottom',
          },
          mobileLayout: 'drawer',
        });

        return true;
      },
      menuConfig: {
        tags: 'Poll_plugin_search_tags',
      },
    },
  ];
};
