/* oxlint-disable jsx-a11y/no-static-element-interactions */
/* oxlint-disable jsx-a11y/click-events-have-key-events */
import cls from 'classnames';
import React, { PureComponent } from 'react';

import { observeElementSize } from './../../../_shared/observe-element-size.js';
import { getScaleImageSrc } from './../../../wix-rich-content-common/lib/image-utils.js';

import { LoaderIcon } from '../../assets/icons/loader-icon.js';
import { ReplaceIcon } from '../../assets/icons/replace-icon.js';
import { POLL_IMAGES_POOL } from '../../defaults.js';
import { getRandomValue } from '../../helpers.js';
import type { RCEHelpersProps } from '../rce-helpers-context/index.js';
import { withRCEHelpers } from '../rce-helpers-context/index.js';
import styles from './image-upload-scss.js';

type Props = RCEHelpersProps & {
  dataHook?: string;
  value?: string;
  onChange: (...args: $TSFixMe[]) => void;
  className?: string;
  imagesPool?: $TSFixMe[];
  small?: boolean;
  disabled?: boolean;
  style?: React.CSSProperties;
};

type State = { value: string; backgroundImage: string | null; loading: boolean };

type Size = { width: number; height: number };

class ImageUploadComponent extends PureComponent<Props, State> {
  static defaultProps = {
    imagesPool: [],
    disabled: false,
  };

  state = {
    value: this.props.value || getRandomValue(POLL_IMAGES_POOL),
    backgroundImage: null,
    loading: false,
  };

  $label = React.createRef();

  private containerRef = React.createRef<HTMLDivElement>();

  private lastSize?: Size;

  private stopObserving?: () => void;

  componentDidMount() {
    const element = this.containerRef.current;
    if (element) {
      this.stopObserving = observeElementSize(element, size => {
        this.lastSize = size;
        this.updateBackgroundImage(size);
      });
    }
  }

  componentWillReceiveProps(props: Props) {
    if (props.value && props.value !== this.props.value) {
      this.setState({ value: props.value }, () => this.updateBackgroundImage());
    }
  }

  componentWillUnmount() {
    this.stopObserving?.();
  }

  sync() {
    this.props.onChange(this.state.value);
  }

  updateBackgroundImage(bounds = this.lastSize) {
    const { value } = this.state;

    if (!bounds?.width || !bounds?.height) {
      return null;
    }

    const backgroundImage = `url(${getScaleImageSrc(value, bounds.width, bounds.height)})`;

    this.setState(() => ({
      backgroundImage,
    }));
  }

  handleFileUpload = ({ data }: $TSFixMe) => {
    this.setState(
      {
        value: `https://static.wixstatic.com/media/${data.file_name}`,
        loading: false,
      },
      () => {
        this.updateBackgroundImage();
        // to avoid the "flushSync was called from inside a lifecycle method" error:
        setTimeout(() => this.sync());
      }
    );
  };

  handleFileReadLoad = (backgroundImage: $TSFixMe, file: $TSFixMe) => {
    this.setState({ backgroundImage: `url(${backgroundImage})`, loading: false });

    this.setState({ loading: true });
    this.props.rce.handleFileUpload(file, this.handleFileUpload);
  };

  handleInputChange = (e: $TSFixMe) => {
    this.handleFileChange(Array.from(e.target.files));
    e.target.value = null;
  };

  handleFileChange = ([file]: $TSFixMe) => {
    const reader = new FileReader();

    this.setState({ loading: true });

    reader.onload = (e: $TSFixMe) => this.handleFileReadLoad(e.target.result, file);
    reader.readAsDataURL(file);
  };

  handleKeyPress = (e: $TSFixMe) => {
    const enterOrSpace =
      e.key === 'Enter' ||
      e.key === ' ' ||
      e.key === 'Spacebar' ||
      e.which === 13 ||
      e.which === 32;

    if (enterOrSpace) {
      e.preventDefault();
      // @ts-expect-error
      this.$label.current?.click();
    }
  };

  handleFocus = (e: $TSFixMe) => {
    e.stopPropagation();
    const { rce } = this.props;
    rce.setInPluginEditingMode(true);
  };

  handleBlur = () => {
    const { rce } = this.props;
    rce.setInPluginEditingMode(false);
  };

  render() {
    const { dataHook, className, rce, small, disabled, style = {} } = this.props;
    const { loading, backgroundImage } = this.state;

    return (
      <div
        ref={this.containerRef}
        className={cls(styles.container, className, {
          [styles.disabled]: rce.isViewMode || disabled,
        })}
        style={{ ...style, backgroundImage: backgroundImage ?? undefined }}
        tabIndex={rce.isViewMode ? -1 : 0}
        aria-hidden={rce.isViewMode}
        role="button"
        onFocus={this.handleFocus}
        onBlur={this.handleBlur}
        onKeyPress={this.handleKeyPress}
        data-hook={dataHook}
      >
        {/* @ts-expect-error */}
        <label ref={this.$label}>
          <input
            type="file"
            disabled={rce.isViewMode || disabled}
            onChange={this.handleInputChange}
            accept="image/*"
            tabIndex={-1}
            className={styles.imageInput}
          />
          <div
            className={cls(styles.overlay, {
              [styles.shown]: loading,
            })}
          >
            {loading ? (
              <LoaderIcon
                width={small ? 24 : 48}
                height={small ? 24 : 48}
                className={styles.spinner}
              />
            ) : (
              <>
                <ReplaceIcon />
                <p
                  className={cls(styles.text, {
                    [styles.hide]: small,
                  })}
                >
                  Change Image
                </p>
              </>
            )}
          </div>
        </label>
      </div>
    );
  }
}

export const ImageUpload = withRCEHelpers(ImageUploadComponent);
