import type { IconComponent } from '@wix/wix-ui-icons-common/core';
import { LayoutGallery, LayoutGallerySmall, List, ListSmall } from '@wix/wix-ui-icons-common/lazy';
import React, { useContext } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import { useModalService } from './../../ricos-modals/modal-service-provider.js';
import { DropdownModal } from './../../_shared/dropdown-modal/dropdown-modal.js';
import { ListItemDivider } from './../../_shared/list-item-divider/list-item-divider.js';
import { ListItemSelect } from './../../_shared/list-item-select/list-item-select.js';

import { POLL_LAYOUT_DROPDOWN_MODAL_ID } from '../consts.js';
import {
  LAYOUT_DROPDOWN_OPTION_CUSTOMIZE_LAYOUT,
  LAYOUT_DROPDOWN_OPTION_GRID,
  LAYOUT_DROPDOWN_OPTION_LIST,
} from '../data-hooks.js';

type Props = {
  selectedLayout: SupportedLayouts;
  onLayoutClick: (commandKey: string) => void;
  onCustomizeButtonClick: () => void;
};

export const PollLayoutDropdown: React.FC<Props> = ({
  selectedLayout,
  onLayoutClick,
  onCustomizeButtonClick,
}) => {
  const { t, isMobile } = useContext(RicosContext);
  const modals = useModalService();

  return (
    <DropdownModal
      title={t('Poll_PollSettings_Tab_Layout_Section_Answers_Layout')}
      onCloseButtonClick={() => modals.closeModal(POLL_LAYOUT_DROPDOWN_MODAL_ID)}
      options={[
        ...Object.entries(dropdownOptions).map(
          ([layout, { dataHook, icon: Icon, iconSmall: IconSmall, text }]) => {
            return (
              <ListItemSelect
                key={layout}
                title={t(text)}
                dataHook={dataHook}
                prefix={isMobile ? <Icon /> : <IconSmall />}
                selected={layout === selectedLayout}
                onSelect={() => onLayoutClick(layout)}
              />
            );
          }
        ),
        <ListItemDivider key="divider" />,
        <ListItemSelect
          key="customize"
          title={t('Poll_Mobile_Editor_Toolbar_Customize')}
          dataHook={LAYOUT_DROPDOWN_OPTION_CUSTOMIZE_LAYOUT}
          onSelect={onCustomizeButtonClick}
        />,
      ]}
    />
  );
};

export type SupportedLayouts = 'GRID' | 'LIST';

export const dropdownOptions: Record<
  SupportedLayouts,
  {
    text: string;
    icon: IconComponent;
    iconSmall: IconComponent;
    dataHook: string;
  }
> = {
  GRID: {
    text: 'Poll_PollSettings_Tab_Layout_Section_Answers_Layout_Grid',
    icon: LayoutGallery,
    iconSmall: LayoutGallerySmall,
    dataHook: LAYOUT_DROPDOWN_OPTION_GRID,
  },
  LIST: {
    text: 'Poll_PollSettings_Tab_Layout_Section_Answers_Layout_List',
    icon: List,
    iconSmall: ListSmall,
    dataHook: LAYOUT_DROPDOWN_OPTION_LIST,
  },
};
