import { Tabs } from '@wix/design-system';
import React, { useContext } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';

import type { SettingsType } from '../../consts.js';
import { SETTINGS_TAB } from '../../consts.js';
import {
  SETTINGS_DESIGN_TAB,
  SETTINGS_GENERAL_TAB,
  SETTINGS_LAYOUT_TAB,
  SETTINGS_TABS,
} from '../../data-hooks.js';

type TabNavigationProps = {
  activeTab: SettingsType;
  onTabChange: (tab: SettingsType) => void;
};

export const TabNavigation: React.FC<TabNavigationProps> = ({ activeTab, onTabChange }) => {
  const { t } = useContext(RicosContext);

  return (
    <Tabs
      dataHook={SETTINGS_TABS}
      minWidth="100%"
      alignment="center"
      type="uniformFull"
      size="small"
      items={[
        {
          id: SETTINGS_TAB.layout,
          dataHook: SETTINGS_LAYOUT_TAB,
          title: t('Poll_PollSettings_Tab_Layout_TabName'),
        },
        {
          id: SETTINGS_TAB.design,
          dataHook: SETTINGS_DESIGN_TAB,
          title: t('Poll_PollSettings_Tab_Design_TabName'),
        },
        {
          id: SETTINGS_TAB.settings,
          dataHook: SETTINGS_GENERAL_TAB,
          title: t('Poll_PollSettings_Tab_Settings_TabName'),
        },
      ]}
      activeId={activeTab}
      onClick={value => onTabChange(value.id as SettingsType)}
    />
  );
};
