import React, { PureComponent } from 'react';

import { cloneDeep } from './../../../_shared/clone-deep.js';

import { OPTION_IMAGES_POOL } from '../../defaults.js';
import { getRandomValue } from '../../helpers.js';

const PollContext = React.createContext({});

export const withPoll = (WrappedComponent: $TSFixMe) => (props: $TSFixMe) => {
  return (
    <PollContext.Consumer>
      {contextValue => {
        return <WrappedComponent {...props} {...contextValue} />;
      }}
    </PollContext.Consumer>
  );
};

type Props = {
  editorEvents?: {
    subscribe: (...args: $TSFixMe[]) => $TSFixMe;
    unsubscribe: (...args: $TSFixMe[]) => $TSFixMe;
  };
  settings?: {
    siteToken?: string;
    isWebView?: boolean;
    getSiteMembers?: (...args: $TSFixMe[]) => $TSFixMe;
    pollServiceApi?: $TSFixMe;
  };
  poll?: $TSFixMe;
  setPoll?: (poll: $TSFixMe) => void;
  children?: React.ReactNode;
  t?: (...args: $TSFixMe[]) => $TSFixMe;
};

export class PollContextProvider extends PureComponent<Props> {
  state: $TSFixMe = {
    changePollTitle: this.changePollTitle.bind(this),
    updatePollOption: this.updatePollOption.bind(this),
    addOption: this.addOption.bind(this),
    removeOption: this.removeOption.bind(this),
    changePollImage: this.changePollImage.bind(this),
    fetchPoll: this.fetchPoll.bind(this),
    vote: this.vote.bind(this),
    unvote: this.unvote.bind(this),
    getVoters: this.getVoters.bind(this),
    poll: this.props.poll,
  };

  constructor(props: $TSFixMe) {
    super(props);
    // @ts-expect-error
    this.pollApiClient = props.settings?.pollServiceApi;
  }

  componentWillReceiveProps(props: $TSFixMe) {
    if (
      !props.settings?.pollServiceApi &&
      // @ts-expect-error
      props.settings.siteToken !== this.props.settings.siteToken
    ) {
      this.fetchPoll();
    }

    if (JSON.stringify(props.poll) !== JSON.stringify(this.props.poll)) {
      this.setState(() => ({ poll: props.poll }));
    }
  }

  componentDidMount() {
    const { editorEvents } = this.props;

    editorEvents?.subscribe('plugin:publish', this.syncPoll);
  }

  componentWillUnmount() {
    this.props.editorEvents?.unsubscribe('plugin:publish', this.syncPoll);
  }

  async fetchPoll() {
    if (!this.state.poll.id) {
      return;
    }

    // @ts-expect-error
    const poll = await this.pollApiClient.fetchPoll(this.state.poll.id);

    this.props.setPoll?.(poll);
    this.setState(() => ({ poll }));
  }

  populateWithData(poll: $TSFixMe) {
    const { t } = this.props;
    poll.title = poll.title || t?.('Poll_Editor_Question_Placeholder');

    poll.options = poll.options.map((option: $TSFixMe) => ({
      ...option,
      title: option.title || t?.('Poll_Editor_Answer_Placeholder'),
    }));

    return poll;
  }

  syncPoll = async () => {
    let dto;
    const poll = this.populateWithData(this.state.poll);

    if (poll.id) {
      // @ts-expect-error
      dto = await this.pollApiClient.updatePoll(poll);
    } else {
      // @ts-expect-error
      dto = await this.pollApiClient.createPoll(poll);
    }

    // @ts-expect-error
    this.props.setPoll(dto);
    console.debug('polls publish callback'); // oxlint-disable-line
  };

  updatePoll(poll: $TSFixMe) {
    // @ts-expect-error
    this.props.setPoll(Object.assign({}, this.state.poll, poll));
  }

  async vote(optionId: $TSFixMe) {
    // @ts-expect-error
    const poll = await this.pollApiClient.vote(this.state.poll.id, optionId);

    this.setState({ poll });
  }

  async unvote(optionId: $TSFixMe) {
    // @ts-expect-error
    const poll = await this.pollApiClient.unvote(this.state.poll.id, optionId);

    this.setState({ poll });
  }

  getVoters(optionId: $TSFixMe, params: $TSFixMe) {
    // @ts-expect-error
    return this.pollApiClient.getVoters(this.state.poll.id, optionId, params);
  }

  changePollTitle(title: $TSFixMe) {
    return this.updatePoll({ title });
  }

  changePollImage(url: $TSFixMe) {
    const imageData = { image: { src: { url } } };
    return this.updatePoll(imageData);
  }

  updatePollOption(index: $TSFixMe, option: $TSFixMe) {
    const poll = cloneDeep(this.state.poll);

    poll.options[index] = option;

    return this.updatePoll({ options: poll.options });
  }

  addOption() {
    const poll = cloneDeep(this.state.poll);
    const imageData = {
      image: {
        src: {
          url: getRandomValue(OPTION_IMAGES_POOL),
        },
      },
    };

    poll.options.push({
      title: '',
      ...imageData,
    });

    return this.updatePoll({ options: poll.options });
  }

  removeOption(index: $TSFixMe) {
    const poll = cloneDeep(this.state.poll);

    poll.options.splice(index, 1);

    return this.updatePoll({ options: poll.options });
  }

  render() {
    const { children } = this.props;

    return <PollContext.Provider value={this.state}>{children}</PollContext.Provider>;
  }
}
