import cls from 'classnames';
import React from 'react';

import { ImageUpload } from '../../image-upload/image-upload.js';
import { TextField } from '../../text-field/text-field.js';
import { PollOptionBase } from '../poll-option-base.js';
import styles from './option-webview-scss.js';

export class PollGridOptionWebview extends PollOptionBase {
  render() {
    const { option, dark, t } = this.props;

    return (
      <div
        className={cls(styles.option, styles.grid, {
          [styles.with_image]: this.isImageEnabled(),
          [styles.dark]: dark,
        })}
      >
        {this.isImageEnabled() && (
          <ImageUpload className={styles.image} value={option.image.src.url} />
        )}
        <div className={styles.title}>
          <TextField
            maxLength={60}
            className={cls(styles.input)}
            value={option.title}
            placeholder={t('Poll_Editor_Answer_Placeholder')}
          />
        </div>
      </div>
    );
  }
}
