import React from 'react';

import { PollData_Layout_PollLayout_Type } from './../../../ricos-schema/legacy/wix/rich_content/v1/index.js';

import { withRCEHelpers } from '../rce-helpers-context/index.js';
import { PollGridOption } from './poll-grid-option.js';
import { PollListOption } from './poll-list-option.js';
import { PollGridOptionWebview } from './webview/poll-grid-option-webview.js';
import { PollListOptionWebview } from './webview/poll-list-option-webview.js';

export const PollOption = withRCEHelpers((props: $TSFixMe) => {
  const { layout, rce } = props;

  if (rce.isWebView) {
    switch (layout.poll?.type) {
      case PollData_Layout_PollLayout_Type.GRID:
        return <PollGridOptionWebview {...props} />;

      case PollData_Layout_PollLayout_Type.LIST:
      default:
        return <PollListOptionWebview {...props} />;
    }
  }

  switch (layout.poll?.type) {
    case PollData_Layout_PollLayout_Type.GRID:
      return <PollGridOption {...props} />;

    case PollData_Layout_PollLayout_Type.LIST:
    default:
      return <PollListOption {...props} />;
  }
});
