import React from 'react';

import type { PluginProps } from './../../ricos-types/index.js';
import { NodeSelection } from './../../tiptap/pm/state.js';

import PollViewer from '../viewer/poll-viewer.js';

export const Poll: React.FC<PluginProps> = ({
  settings,
  componentData,
  node,
  updateAttributes,
  selected,
  editor,
}) => {
  const block = { getKey: () => node.attrs.id };
  const isOnlySelected =
    selected &&
    editor.state.selection instanceof NodeSelection &&
    editor.state.selection.node.attrs.id === node.attrs.id;

  return (
    <div>
      <PollViewer
        componentData={componentData}
        settings={settings}
        updateAttributes={updateAttributes}
        block={block}
        selected={selected}
        isOnlySelected={isOnlySelected}
      />
    </div>
  );
};
