import type { members } from '@wix/members';
import React from 'react';

import { isSSR } from './../../_shared/is-ssr.js';
import type { GetWixClientPromise } from './../../_shared/request-service-provider/use-get-wix-client-promise.js';
import { useWixInstanceService } from './../../_shared/request-service-provider/wix-instance-context.js';

import { PollsService } from '../services/polls-service.js';
import type { PollPluginEditorConfig, PollPluginViewerConfig, PollsMember } from '../types.js';

const getMembersModulePromise = () => {
  return import(/* webpackChunkName: "wix-ricos-members" */ '@wix/members').then(
    module => module.members
  );
};

const fetchMembers = (
  membersIds: string[],
  getWixClientPromise: GetWixClientPromise
): Promise<PollsMember[]> =>
  Promise.all([getWixClientPromise(), getMembersModulePromise()]).then(
    ([wixClient, membersModule]) =>
      wixClient
        .use(membersModule)
        .queryMembers()
        .in('_id', membersIds)
        .find()
        .then(res => normalizeMembers(res.items))
        .catch(e => {
          // Rethrow instead of resolving to an empty list: a failed request must
          // not be indistinguishable from "member not found", or the resulting
          // placeholder gets cached permanently and voters stay nameless for the
          // rest of the page lifetime. Rethrowing lets `loadMember` evict and retry.
          // oxlint-disable-next-line no-console
          console.error('[pollsStrategy] fetchMembers failed. error:', e);
          throw e;
        })
  );

// Module-level per-member cache so each member is fetched at most once across
// all poll viewers on the page (the cached value is the in-flight promise, so
// concurrent requests for the same member share a single fetch).
const membersCache = new Map<string, Promise<PollsMember>>();

// `res.items` may be absent, so the parameter is optional rather than relying on
// optional chaining that the declared return type would hide.
const normalizeMembers = (rawMembers?: members.Member[]): PollsMember[] =>
  (rawMembers ?? []).map(member => {
    return {
      siteMemberId: member._id ?? undefined,
      imageUrl: member.profile?.photo?.url ?? undefined,
      name: {
        nick: member.profile?.nickname ?? undefined,
      },
    };
  });

// Exported for testing.
export const createGetSiteMembers = (getWixClientPromise: GetWixClientPromise) => {
  if (isSSR()) {
    return undefined;
  }

  // Coalesce every member id requested within the same tick into one request
  // (the batching DataLoader provided) via a pending queue flushed on a
  // microtask.
  let pendingIds: string[] = [];
  let pendingFetch: Promise<Map<string | undefined, PollsMember>> | null = null;

  const scheduleFetch = () => {
    if (pendingFetch) {
      return pendingFetch;
    }
    const fetch = Promise.resolve().then(() => {
      const ids = pendingIds;
      pendingIds = [];
      pendingFetch = null;
      return fetchMembers(ids, getWixClientPromise).then(
        fetchedMembers =>
          new Map<string | undefined, PollsMember>(
            fetchedMembers.map(member => [member.siteMemberId, member])
          )
      );
    });
    pendingFetch = fetch;
    return fetch;
  };

  const loadMember = (id: string): Promise<PollsMember> => {
    const cached = membersCache.get(id);
    if (cached) {
      return cached;
    }
    pendingIds.push(id);
    const memberPromise = scheduleFetch()
      // A member missing from a *successful* response genuinely doesn't exist,
      // so the bare-id placeholder is a legitimate cacheable value.
      .then(membersById => membersById.get(id) ?? { siteMemberId: id })
      // Failures (wix client / members module load, or the members query itself)
      // are not cached — evict so a later call can retry, as DataLoader did.
      .catch(error => {
        membersCache.delete(id);
        throw error;
      });
    membersCache.set(id, memberPromise);
    return memberPromise;
  };

  return (memberIds: string[]): Promise<PollsMember[]> => Promise.all(memberIds.map(loadMember));
};

// oxlint-disable-next-line @typescript-oxlint/explicit-module-boundary-types
export const usePollServices = (settings: PollPluginViewerConfig | PollPluginEditorConfig) => {
  const wixInstance = useWixInstanceService();
  const { getWixClientPromise } = wixInstance();

  return React.useMemo(() => {
    if (settings.pollServiceApi || !getWixClientPromise) {
      return settings;
    }
    return {
      ...settings,
      pollServiceApi: new PollsService(getWixClientPromise),
      getSiteMembers: createGetSiteMembers(getWixClientPromise),
    };
  }, [settings, getWixClientPromise]);
};
