import type { Poll } from './components/poll-context/poll-types.js';

export const POLL_TYPE = 'wix-draft-plugin-poll';

export type PollServiceApi = {
  fetchPoll: (pollId: string) => Promise<Poll>;
  createPoll: (poll: Poll) => Promise<Poll>;
  updatePoll: (poll: Poll) => Promise<Poll>;
  vote: (pollId: string, optionId: string) => Promise<Poll>;
  unvote: (pollId: string, optionId: string) => Promise<Poll>;

  getVoters: (pollId: string, optionId: string, params: any) => Promise<any>;
};

export interface PollPluginEditorConfig {
  type: 'poll';
  pollServiceApi?: PollServiceApi;
  showVoteRoleSetting?: boolean;
  /**
   * @default false
   */
  isWebView?: boolean;
  voteRole?: string;
  /**
   * @deprecated not supported in editor
   */
  onBeforeVote?: ({ voteRole }: { voteRole?: string }) => Promise<void>;
}
export interface PollPluginViewerConfig {
  pollServiceApi?: PollServiceApi;
  onBeforeVote?: ({ voteRole }: { voteRole?: string }) => Promise<void>;
  getSiteMembers?: (ids: string[]) => Promise<PollsMember[]>;
  /**
   * @deprecated not supported in viewer
   */
  voteRole?: string;
  /**
   * @deprecated not supported in viewer
   */
  showVoteRoleSetting?: boolean;
  /**
   * @default false
   */
  isWebView?: boolean;
}

export type PollsMember = {
  siteMemberId?: string;
  imageUrl?: string;
  name?: {
    nick?: string;
  };
};
