import React, { useContext } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import type { ComponentData } from './../../ricos-types/index.js';
import { withEditorEvents } from './../../editor-common/editor-events-context.js';

import { PollContextProvider } from '../components/poll-context/poll-context.js';
import { RCEHelpersContext } from '../components/rce-helpers-context/index.js';
import { usePollServices } from '../hooks/use-poll-services.js';
import type { PollPluginEditorConfig, PollPluginViewerConfig } from '../types.js';
import { Poll } from './poll-component.js';

interface Props {
  componentData: ComponentData;
  selected: boolean;
  settings: PollPluginViewerConfig | PollPluginEditorConfig;
  updateAttributes?: (attributes: $TSFixMe) => void;

  editorEvents: any;
  isViewMode?: boolean;
  isOnlySelected?: boolean;
}

const Polls: React.FC<Props> = props => {
  const { theme, t, isMobile } = useContext(RicosContext);

  const setPoll = (poll: $TSFixMe) => {
    const { updateAttributes } = props;
    updateAttributes?.({ poll });
  };

  const {
    componentData,
    editorEvents,
    selected,
    isViewMode = false,
    settings,
    isOnlySelected,
  } = props;

  const resolvedSettings = usePollServices(settings);

  return (
    <RCEHelpersContext.Provider
      value={{
        isViewMode: isViewMode
          ? isViewMode
          : resolvedSettings.isWebView || typeof selected === 'boolean'
            ? !selected
            : true,
        setInPluginEditingMode: () => {},
        layout: componentData.layout,
        design: componentData.design,
        preventVoting: !isViewMode,
        isPreview: !!resolvedSettings.isWebView,
        theme,
        t,
        isMobile,
        isOnlySelected,
        ...resolvedSettings,
      }}
    >
      <PollContextProvider
        editorEvents={editorEvents}
        settings={resolvedSettings}
        poll={componentData.poll}
        setPoll={setPoll}
        t={t}
      >
        <Poll />
      </PollContextProvider>
    </RCEHelpersContext.Provider>
  );
};

export default withEditorEvents(Polls);
